import{_ as a,C as e,c as o,o as s,j as t,b as r,a0 as i,a as d,w as n,G as l,a1 as c}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Tomada de decisão baseada em probabilidade","description":"","frontmatter":{},"headers":[],"relativePath":"pt/education/tactics/probability.md","filePath":"pt/education/tactics/probability.md"}');const m=a({name:"pt/education/tactics/probability.md"},[["render",function(a,u,m,p,h,b){const g=e("Mermaid");return s(),o("div",null,[u[1]||(u[1]=t("h1",{id:"tomada-de-decisao-baseada-em-probabilidade",tabindex:"-1"},[d("Tomada de decisão baseada em probabilidade "),t("a",{class:"header-anchor",href:"#tomada-de-decisao-baseada-em-probabilidade","aria-label":'Permalink to "Tomada de decisão baseada em probabilidade"'},"​")],-1)),u[2]||(u[2]=t("p",null,"O pensamento tático de elite utiliza a probabilidade para tomar decisões melhores. Em vez de adivinhar ou seguir a intuição, você pensa sistematicamente sobre suas opções.",-1)),u[3]||(u[3]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"A Grande Ideia"),t("p",null,[t("strong",null,"Pense em probabilidades, não em certezas."),d(" A melhor decisão nem sempre é a mais agressiva ou a mais segura – é aquela que oferece o melhor valor esperado em diversas situações semelhantes.")])],-1)),(s(),r(c,null,{default:n(()=>[l(g,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BPonto%20de%20decis%C3%A3o%5D%20--%3E%20B%5BOp%C3%A7%C3%A3o%201%5D%0A%20%20%20%20A%20--%3E%20C%5BOp%C3%A7%C3%A3o%202%5D%0A%20%20%20%20A%20--%3E%20D%5BOp%C3%A7%C3%A3o%203%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BProbabilidade%20de%20sucesso%5D%0A%20%20%20%20B%20--%3E%20F%5BRecompensa%20em%20caso%20de%20sucesso%5D%0A%20%20%20%20B%20--%3E%20G%5BCusto%20em%20caso%20de%20falha%5D%0A%0A%20%20%20%20C%20--%3E%20H%5BProbabilidade%20de%20sucesso%5D%0A%20%20%20%20C%20--%3E%20I%5BRecompensa%20em%20caso%20de%20sucesso%5D%0A%20%20%20%20C%20--%3E%20J%5BCusto%20em%20caso%20de%20falha%5D%0A%0A%20%20%20%20D%20--%3E%20K%5BProbabilidade%20de%20sucesso%5D%0A%20%20%20%20D%20--%3E%20L%5BRecompensa%20em%20caso%20de%20sucesso%5D%0A%20%20%20%20D%20--%3E%20M%5BCusto%20em%20caso%20de%20falha%5D%0A%0A%20%20%20%20E%20--%3E%20N%5BValor%20esperado%5D%0A%20%20%20%20F%20--%3E%20N%0A%20%20%20%20G%20--%3E%20N%0A%0A%20%20%20%20H%20--%3E%20O%5BValor%20esperado%5D%0A%20%20%20%20I%20--%3E%20O%0A%20%20%20%20J%20--%3E%20O%0A%0A%20%20%20%20K%20--%3E%20P%5BValor%20esperado%5D%0A%20%20%20%20L%20--%3E%20P%0A%20%20%20%20M%20--%3E%20P%0A%0A%20%20%20%20N%20--%3E%20Q%5BEscolha%20o%20melhor%20ve%C3%ADculo%20el%C3%A9trico%5D%0A%20%20%20%20O%20--%3E%20Q%0A%20%20%20%20P%20--%3E%20Q%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20Q%20fill%3A%23fff4e1%0A"})]),fallback:n(()=>[...u[0]||(u[0]=[d(" Loading... ",-1)])]),_:1})),u[4]||(u[4]=i('<h2 id="a-estrutura-basica" tabindex="-1">A estrutura básica <a class="header-anchor" href="#a-estrutura-basica" aria-label="Permalink to &quot;A estrutura básica&quot;">​</a></h2><p>Cada arremesso possui três componentes:</p><table tabindex="0"><thead><tr><th>Componente</th><th>Pergunta</th><th>Exemplo</th></tr></thead><tbody><tr><td><strong>Probabilidade de sucesso</strong></td><td>Qual a probabilidade de eu conseguir executar isso?</td><td>Taxa de sucesso de 70% a essa distância.</td></tr><tr><td><strong>Recompensa em caso de sucesso</strong></td><td>O que eu ganho com isso?</td><td>Ganhe o ponto, ganhe posição</td></tr><tr><td><strong>Custo em caso de insucesso</strong></td><td>O que eu perco?</td><td>Dê pontos fáceis ao adversário.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">A Fórmula</p><p><strong>Valor Esperado = (Probabilidade × Recompensa) - ((1 - Probabilidade) × Custo)</strong></p><p>Boas decisões maximizam o valor esperado ao longo do tempo.</p></div><h2 id="pensando-em-probabilidades" tabindex="-1">Pensando em Probabilidades <a class="header-anchor" href="#pensando-em-probabilidades" aria-label="Permalink to &quot;Pensando em Probabilidades&quot;">​</a></h2><p>Ao escolher entre as opções, considere:</p><ul><li>Qual é a minha taxa de sucesso realista para cada opção?</li><li>O que eu ganho se isso funcionar?</li><li>Qual o custo se falhar?</li><li>Como a situação do jogo afeta minha escolha?</li></ul><p>A melhor opção nem sempre é a mais agressiva ou a mais segura – é aquela que oferece o melhor resultado em diversas situações semelhantes.</p><h2 id="conheca-seus-numeros" tabindex="-1">Conheça seus números <a class="header-anchor" href="#conheca-seus-numeros" aria-label="Permalink to &quot;Conheça seus números&quot;">​</a></h2><p>Para usar o raciocínio probabilístico, você precisa conhecer suas taxas de sucesso reais:</p><table tabindex="0"><thead><tr><th>Tipo de arremesso</th><th>Distância</th><th>Sua taxa de sucesso</th></tr></thead><tbody><tr><td>Ponto (fechar)</td><td>6-7m</td><td>___%</td></tr><tr><td>Ponto (médio)</td><td>8-9m</td><td>___%</td></tr><tr><td>Ponto (longo)</td><td>10m+</td><td>___%</td></tr><tr><td>Atirar (de perto)</td><td>6-7m</td><td>___%</td></tr><tr><td>Tiro (médio)</td><td>8-9m</td><td>___%</td></tr><tr><td>Tiro (longo)</td><td>10m+</td><td>___%</td></tr></tbody></table><p>Acompanhe isso na prática. Seja honesto: a maioria dos jogadores superestima suas taxas de sucesso.</p><h2 id="ajustando-as-condicoes" tabindex="-1">Ajustando às condições <a class="header-anchor" href="#ajustando-as-condicoes" aria-label="Permalink to &quot;Ajustando às condições&quot;">​</a></h2><p>Suas tarifas base variam de acordo com:</p><table tabindex="0"><thead><tr><th>Fator</th><th>Efeito na taxa de sucesso</th></tr></thead><tbody><tr><td>terreno desconhecido</td><td>-10 a -20%</td></tr><tr><td>Situação de pressão</td><td>-5 a -15%</td></tr><tr><td>Fadiga</td><td>-5 a -10%</td></tr><tr><td>Confiança (alta)</td><td>+5 a +10%</td></tr><tr><td>Sucesso recente</td><td>+5%</td></tr><tr><td>Falha recente</td><td>-5 a -10%</td></tr></tbody></table><p>Seja realista quanto a esses ajustes.</p><h2 id="o-principio-da-vantagem-da-boule" tabindex="-1">O Princípio da Vantagem da Boule <a class="header-anchor" href="#o-principio-da-vantagem-da-boule" aria-label="Permalink to &quot;O Princípio da Vantagem da Boule&quot;">​</a></h2><p>Quando você tiver mais bolas restantes do que seu oponente:</p><p><strong>Prioridade 1: Garantir o ponto</strong></p><ul><li>Primeiro, certifique-se de estar segurando pelo menos um ponto.</li><li>Não seja ganancioso antes de garantir o básico.</li></ul><p><strong>Prioridade 2: Maximizar pontos com risco calculado</strong></p><ul><li>Depois de conseguir segurar a posição, avalie se consegue adicionar mais pontos.</li><li>Cada lançamento adicional é uma decisão de risco/recompensa.</li><li>Não transforme uma vitória segura por 2 pontos em uma derrota por excesso de zelo.</li></ul><p><strong>Poucas bolas restantes:</strong> Você precisa fazer com que cada arremesso conte. Jogadas conservadoras podem não ser suficientes - considere opções com maior potencial de recompensa para se recuperar no final.</p><h2 id="o-principio-quot-une-boule-devant-quot" tabindex="-1">O Princípio &quot;Une Boule Devant&quot; <a class="header-anchor" href="#o-principio-quot-une-boule-devant-quot" aria-label="Permalink to &quot;O Princípio &amp;quot;Une Boule Devant&amp;quot;&quot;">​</a></h2><p>Uma bola em frente ao bolim (entre o bolim e o adversário) é extremamente valiosa:</p><ul><li>Ele bloqueia linhas de apontamento direto.</li><li>Isso força os adversários a contornar ou passar por cima.</li><li>Ele pode desviar bolas de projéteis que se aproximam.</li><li>É uma &quot;bola de dinheiro&quot; - que vale a pena proteger.</li></ul><p><strong>Implicação tática:</strong> Às vezes, posicionar uma bola de bloqueio é melhor do que tentar chegar mais perto.</p><h2 id="tolerancia-ao-risco-por-estado-do-jogo" tabindex="-1">Tolerância ao risco por estado do jogo <a class="header-anchor" href="#tolerancia-ao-risco-por-estado-do-jogo" aria-label="Permalink to &quot;Tolerância ao risco por estado do jogo&quot;">​</a></h2><h3 id="com-limite-de-tempo" tabindex="-1">Com limite de tempo <a class="header-anchor" href="#com-limite-de-tempo" aria-label="Permalink to &quot;Com limite de tempo&quot;">​</a></h3><p>Ao jogar com limite de tempo, a diferença de pontuação importa:</p><table tabindex="0"><thead><tr><th>Situação da pontuação</th><th>Abordagem de Risco</th></tr></thead><tbody><tr><td>Liderando por mais de 4</td><td>Muito conservador - proteger o líder, deixar o relógio correr.</td></tr><tr><td>Liderando por 1-3</td><td>Conservador - não ceda pontos</td></tr><tr><td>Ligado</td><td>Equilibrado - riscos calculados</td></tr><tr><td>Perdendo por 1-3</td><td>Agressivo - precisa ganhar terreno</td></tr><tr><td>Atrás por mais de 4</td><td>Muito agressivo - é preciso arriscar, o tempo está se esgotando.</td></tr></tbody></table><h3 id="sem-limite-de-tempo" tabindex="-1">Sem limite de tempo <a class="header-anchor" href="#sem-limite-de-tempo" aria-label="Permalink to &quot;Sem limite de tempo&quot;">​</a></h3><p>Quando não há pressão de tempo:</p><ul><li>Mantenha-se fiel ao seu plano de jogo - não mude de estratégia só por causa do placar.</li><li>A pontuação irá oscilar - confie na sua abordagem.</li><li>Considere mudar sua estratégia apenas se ela claramente não estiver funcionando contra esse adversário.</li><li>Mudanças de atitude em pânico quando se está em desvantagem geralmente pioram as coisas.</li></ul><h3 id="ajustes-de-fim-de-jogo" tabindex="-1">Ajustes de fim de jogo <a class="header-anchor" href="#ajustes-de-fim-de-jogo" aria-label="Permalink to &quot;Ajustes de fim de jogo&quot;">​</a></h3><p><strong>Se vencer esta extremidade significar vencer o jogo:</strong></p><ul><li>Seja mais conservador</li><li>Não arrisque perder vários pontos.</li><li>Um único ponto pode ser suficiente.</li></ul><p><strong>Se perder esta extremidade, perde o jogo:</strong></p><ul><li>Assumir riscos maiores</li><li>Precisa marcar vários pontos</li><li>Jogar pelo seguro não vai te salvar.</li></ul><h2 id="erros-comuns-em-probabilidade" tabindex="-1">Erros comuns em probabilidade <a class="header-anchor" href="#erros-comuns-em-probabilidade" aria-label="Permalink to &quot;Erros comuns em probabilidade&quot;">​</a></h2><h3 id="_1-excesso-de-confianca" tabindex="-1">1. Excesso de confiança <a class="header-anchor" href="#_1-excesso-de-confianca" aria-label="Permalink to &quot;1. Excesso de confiança&quot;">​</a></h3><p>&quot;Eu consigo acertar esse arremesso&quot; - mas você consegue acertá-lo 7 vezes em 10? Seja sincero.</p><h3 id="_2-ignorando-as-taxas-basicas" tabindex="-1">2. Ignorando as taxas básicas <a class="header-anchor" href="#_2-ignorando-as-taxas-basicas" aria-label="Permalink to &quot;2. Ignorando as taxas básicas&quot;">​</a></h3><p>Sua porcentagem de acertos nos arremessos não muda porque o momento é importante.</p><h3 id="_3-falacia-do-custo-irrecuperavel" tabindex="-1">3. Falácia do Custo Irrecuperável <a class="header-anchor" href="#_3-falacia-do-custo-irrecuperavel" aria-label="Permalink to &quot;3. Falácia do Custo Irrecuperável&quot;">​</a></h3><p>&quot;Já errei duas vezes, devo continuar tentando&quot; - cada arremesso é independente.</p><h3 id="_4-vies-de-resultado" tabindex="-1">4. Viés de resultado <a class="header-anchor" href="#_4-vies-de-resultado" aria-label="Permalink to &quot;4. Viés de resultado&quot;">​</a></h3><p>Uma jogada arriscada que deu certo continuava sendo arriscada. Uma jogada segura que falhou continuava sendo correta.</p><h3 id="_5-ignorar-as-opcoes-do-oponente" tabindex="-1">5. Ignorar as opções do oponente <a class="header-anchor" href="#_5-ignorar-as-opcoes-do-oponente" aria-label="Permalink to &quot;5. Ignorar as opções do oponente&quot;">​</a></h3><p>Considere o que eles farão depois do seu arremesso, seja ele bem-sucedido ou não.</p><h2 id="aplicacao-pratica" tabindex="-1">Aplicação prática <a class="header-anchor" href="#aplicacao-pratica" aria-label="Permalink to &quot;Aplicação prática&quot;">​</a></h2><h3 id="antes-de-cada-arremesso" tabindex="-1">Antes de cada arremesso <a class="header-anchor" href="#antes-de-cada-arremesso" aria-label="Permalink to &quot;Antes de cada arremesso&quot;">​</a></h3><ol><li><strong>Identificar opções</strong> (apontar, atirar, bloquear, etc.)</li><li><strong>Estime a probabilidade de sucesso</strong> para cada um</li><li><strong>Considere os resultados</strong> (sucesso e fracasso)</li><li><strong>Considere o estado do jogo</strong> (pontuação, bolas restantes)</li><li><strong>Escolha</strong> a opção com o melhor valor esperado.</li><li><strong>Comprometa-se totalmente</strong> - sem hesitações durante a execução.</li></ol><h3 id="desenvolvendo-a-intuicao" tabindex="-1">Desenvolvendo a intuição <a class="header-anchor" href="#desenvolvendo-a-intuicao" aria-label="Permalink to &quot;Desenvolvendo a intuição&quot;">​</a></h3><p>Com o tempo, o pensamento probabilístico torna-se intuitivo:</p><ul><li>Acompanhe seus resultados com honestidade.</li><li>Analisar as decisões após os jogos</li><li>Observe os padrões nas suas taxas de sucesso.</li><li>Ajuste seu modelo mental</li></ul><h2 id="ponto-chave" tabindex="-1">Ponto-chave <a class="header-anchor" href="#ponto-chave" aria-label="Permalink to &quot;Ponto-chave&quot;">​</a></h2><blockquote><p>Boas decisões nem sempre levam a bons resultados. Mas boas decisões ao longo do tempo levam a melhores resultados.</p></blockquote><p>Pense em probabilidades. Conheça os números. Faça a jogada inteligente, não a jogada baseada na esperança.</p>',59))])}]]);export{u as __pageData,m as default};
